                raise
            return existed

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_locked()
            if key not in self.entries:
                return False
            previous = self.entries.pop(key)
            try:
                self._persist_locked()
            except Exception:
                self.entries[key] = previous
                raise
            return True


