        try:
            route, key = self._path()
            allowed = {
                "health": {"GET"},
                "keys": {"GET"},
                "kv": {"GET", "PUT", "DELETE"},
            }[route]
            if method not in allowed:
                self.send_response(HTTPStatus.METHOD_NOT_ALLOWED)
